import csv,sqlite3
with open('csv/frpm.csv') as f:
    frpm = list(csv.DictReader(f))
cds2sch = {}
for r in frpm:
    if r['CDSCode'] not in cds2sch:
        cds2sch[r['CDSCode']] = {'name': r['School Name'], 'funding': r['Charter Funding Type'], 'district': r['District Name']}
conn = sqlite3.connect('db/satscores.db')
cur = conn.cursor()
cur.execute('SELECT cds, AvgScrMath FROM satscores')
scores = {row[0]: row[1] for row in cur.fetchall()}
conn.close()
rv_dists = {'Riverside County Office of Education', 'California School for the Deaf-Riverside (State Special Schl)', 'Riverside Unified'}
dist_scores = {}
for cds, math in scores.items():
    if cds not in cds2sch: continue
    d = cds2sch[cds]['district']
    if d not in rv_dists: continue
    if math:
        if d not in dist_scores: dist_scores[d] = []
        dist_scores[d].append(math)
avg_dist = {d: sum(v)/len(v) for d, v in dist_scores.items()}
qual_dists = {d for d, a in avg_dist.items() if a > 400}
res = []
for cds, sch in cds2sch.items():
    if sch['district'] in qual_dists:
        res.append((sch['name'], sch['funding']))
print('\n'.join(str(r) for r in res))

